// CO1 (docs/37_COLOUR.md): pure colour-reference helpers over Sanzo Wada's
// 159 published colours. No DOM.
//
// WADA_PAIRS/PARTNERS_INDEX are generated by scripts/build-palette-ref.mjs
// from docs/design/colour/colors.json — never hand-edit
// src/ui/palette-ref.generated.js.
import { WADA_PAIRS, PARTNERS_INDEX } from './palette-ref.generated.js';

// Expand the compact [name, hex] rows into the documented {name, hex} shape.
export const WADA = WADA_PAIRS.map(([name, hex]) => ({ name, hex }));

// PARTNERS_INDEX ships by WADA array index to avoid repeating colour names;
// expand it once, here, into the documented name -> {partnerName: count} shape.
export const PARTNERS = Object.fromEntries(
  WADA.map((c, i) => [
    c.name,
    Object.fromEntries(PARTNERS_INDEX[i].map(([j, count]) => [WADA[j].name, count])),
  ])
);

function hexToRgb(hex) {
  const n = parseInt(hex.replace('#', ''), 16);
  return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
}

function srgbToLinear(c) {
  const v = c / 255;
  return v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
}

// sRGB (D65) -> CIE Lab, via XYZ.
export function toLab(hex) {
  const { r, g, b } = hexToRgb(hex);
  const rl = srgbToLinear(r);
  const gl = srgbToLinear(g);
  const bl = srgbToLinear(b);

  const x = rl * 0.4124564 + gl * 0.3575761 + bl * 0.1804375;
  const y = rl * 0.2126729 + gl * 0.7151522 + bl * 0.072175;
  const z = rl * 0.0193339 + gl * 0.119192 + bl * 0.9503041;

  // D65 reference white.
  const xn = x / 0.95047;
  const yn = y / 1.0;
  const zn = z / 1.08883;

  const f = (t) => (t > 0.008856 ? Math.cbrt(t) : 7.787 * t + 16 / 116);
  const fx = f(xn);
  const fy = f(yn);
  const fz = f(zn);

  return {
    L: 116 * fy - 16,
    a: 500 * (fx - fy),
    b: 200 * (fy - fz),
  };
}

function linearToSrgb(v) {
  const c = v <= 0.0031308 ? v * 12.92 : 1.055 * Math.pow(v, 1 / 2.4) - 0.055;
  return Math.max(0, Math.min(255, Math.round(c * 255)));
}

// CIE Lab -> sRGB hex, the inverse of toLab().
export function fromLab({ L, a, b }) {
  const fy = (L + 16) / 116;
  const fx = fy + a / 500;
  const fz = fy - b / 200;

  const fInv = (t) => (t ** 3 > 0.008856 ? t ** 3 : (t - 16 / 116) / 7.787);
  const xn = fInv(fx) * 0.95047;
  const yn = fInv(fy) * 1.0;
  const zn = fInv(fz) * 1.08883;

  const rl = xn * 3.2404542 + yn * -1.5371385 + zn * -0.4985314;
  const gl = xn * -0.969266 + yn * 1.8760108 + zn * 0.041556;
  const bl = xn * 0.0556434 + yn * -0.2040259 + zn * 1.0572252;

  const r = linearToSrgb(rl);
  const g = linearToSrgb(gl);
  const bb = linearToSrgb(bl);
  return (
    '#' + [r, g, bb].map((v) => v.toString(16).padStart(2, '0')).join('')
  );
}

function deg2rad(d) {
  return (d * Math.PI) / 180;
}
function rad2deg(r) {
  return (r * 180) / Math.PI;
}

// CIEDE2000 colour difference between two Lab colours.
export function deltaE(a, b) {
  const labA = typeof a === 'string' ? toLab(a) : a;
  const labB = typeof b === 'string' ? toLab(b) : b;

  const kL = 1;
  const kC = 1;
  const kH = 1;

  const C1 = Math.sqrt(labA.a ** 2 + labA.b ** 2);
  const C2 = Math.sqrt(labB.a ** 2 + labB.b ** 2);
  const Cbar = (C1 + C2) / 2;

  const G =
    0.5 * (1 - Math.sqrt(Cbar ** 7 / (Cbar ** 7 + 25 ** 7)));

  const a1p = labA.a * (1 + G);
  const a2p = labB.a * (1 + G);

  const C1p = Math.sqrt(a1p ** 2 + labA.b ** 2);
  const C2p = Math.sqrt(a2p ** 2 + labB.b ** 2);

  const h1p =
    a1p === 0 && labA.b === 0 ? 0 : (rad2deg(Math.atan2(labA.b, a1p)) + 360) % 360;
  const h2p =
    a2p === 0 && labB.b === 0 ? 0 : (rad2deg(Math.atan2(labB.b, a2p)) + 360) % 360;

  const dLp = labB.L - labA.L;
  const dCp = C2p - C1p;

  let dhp;
  if (C1p * C2p === 0) {
    dhp = 0;
  } else if (Math.abs(h2p - h1p) <= 180) {
    dhp = h2p - h1p;
  } else if (h2p - h1p > 180) {
    dhp = h2p - h1p - 360;
  } else {
    dhp = h2p - h1p + 360;
  }
  const dHp = 2 * Math.sqrt(C1p * C2p) * Math.sin(deg2rad(dhp) / 2);

  const Lbarp = (labA.L + labB.L) / 2;
  const Cbarp = (C1p + C2p) / 2;

  let Hbarp;
  if (C1p * C2p === 0) {
    Hbarp = h1p + h2p;
  } else if (Math.abs(h1p - h2p) <= 180) {
    Hbarp = (h1p + h2p) / 2;
  } else if (h1p + h2p < 360) {
    Hbarp = (h1p + h2p + 360) / 2;
  } else {
    Hbarp = (h1p + h2p - 360) / 2;
  }

  const T =
    1 -
    0.17 * Math.cos(deg2rad(Hbarp - 30)) +
    0.24 * Math.cos(deg2rad(2 * Hbarp)) +
    0.32 * Math.cos(deg2rad(3 * Hbarp + 6)) -
    0.2 * Math.cos(deg2rad(4 * Hbarp - 63));

  const dTheta = 30 * Math.exp(-(((Hbarp - 275) / 25) ** 2));
  const Rc = 2 * Math.sqrt(Cbarp ** 7 / (Cbarp ** 7 + 25 ** 7));
  const Sl =
    1 + (0.015 * (Lbarp - 50) ** 2) / Math.sqrt(20 + (Lbarp - 50) ** 2);
  const Sc = 1 + 0.045 * Cbarp;
  const Sh = 1 + 0.015 * Cbarp * T;
  const Rt = -Math.sin(deg2rad(2 * dTheta)) * Rc;

  return Math.sqrt(
    (dLp / (kL * Sl)) ** 2 +
      (dCp / (kC * Sc)) ** 2 +
      (dHp / (kH * Sh)) ** 2 +
      Rt * (dCp / (kC * Sc)) * (dHp / (kH * Sh))
  );
}

/**
 * The n nearest WADA colours to a hex value, by CIEDE2000, closest first.
 * @param {string} hex
 * @param {number} [n]
 * @returns {{name: string, hex: string, deltaE: number}|Array}
 */
export function nearest(hex, n = 1) {
  const lab = toLab(hex);
  const ranked = WADA.map((c) => ({ ...c, deltaE: deltaE(lab, toLab(c.hex)) })).sort(
    (a, b) => a.deltaE - b.deltaE
  );
  return n === 1 ? ranked[0] : ranked.slice(0, n);
}
